// === PARSE AI AGENT RESPONSE ===
const aiResponse = $input.first().json;

console.log('=== PARSE AI AGENT RESPONSE ===');
console.log('AI Agent Response:', JSON.stringify(aiResponse, null, 2));

let responseText = '';
let needsClarification = false;
let clarificationQuestion = '';
let parsedIntent = null;
let parsedParams = {};
let conversationState = 'executing';

// AI Agent returns data in 'output' field as JSON string
// Handle multiple possible formats:
// 1. Single object: {"output": "JSON_STRING"}
// 2. Array format: [{"output": "JSON_STRING"}]
// 3. Direct content formats
if (aiResponse.output) {
  responseText = aiResponse.output;
  console.log('Extracted from single object format');
} else if (Array.isArray(aiResponse) && aiResponse.length > 0) {
  if (aiResponse[0].output) {
    // Handle array format: [{"output": "JSON_STRING"}]
    responseText = aiResponse[0].output;
    console.log('Extracted from array format:', responseText);
  } else if (aiResponse[0].message && aiResponse[0].message.content) {
    responseText = aiResponse[0].message.content;
  } else {
    responseText = JSON.stringify(aiResponse[0]);
  }
} else if (aiResponse.message && aiResponse.message.content) {
  responseText = aiResponse.message.content;
} else if (aiResponse.text) {
  responseText = aiResponse.text;
} else if (aiResponse.content) {
  responseText = aiResponse.content;
} else {
  responseText = JSON.stringify(aiResponse);
}

console.log('Final extracted response text:', responseText);

// Try to parse JSON response for intent and parameters
try {
  let parsed;

  // Try to parse as direct JSON first (AI Agent often returns clean JSON)
  try {
    parsed = JSON.parse(responseText);
    console.log('Successfully parsed direct JSON:', parsed);
  } catch (e) {
    // If direct parse fails, look for JSON pattern in text
    console.log('Direct JSON parse failed, trying pattern match');
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
      console.log('Successfully parsed extracted JSON:', parsed);
    } else {
      throw new Error('No JSON pattern found');
    }
  }

  // Handle different AI response formats
  if (parsed.intent) {
    // Standard format: {"intent": "action", "params": {...}, "response": "..."}
    parsedIntent = parsed.intent;
    parsedParams = parsed.params || parsed.parameters || {};

    // Check for casual conversation intents that should be treated as chat
    if (['greetings', 'greeting', 'hello', 'hi', 'casual', 'smalltalk'].includes(parsedIntent.toLowerCase())) {
      console.log('Converting greeting/casual intent to chat');
      parsedIntent = 'chat';
      parsedParams = { response: parsed.response || parsed.params?.response || parsed.parameters?.response || 'Hello! How can I help you in Minecraft today?' };
    }

    // Also extract response from top level if available
    if (parsed.response && !parsedParams.response) {
      parsedParams.response = parsed.response;
    }
  } else if (parsed.chat) {
    // Chat format: {"chat": "message"}
    parsedIntent = 'chat';
    parsedParams = { response: parsed.chat };
  } else if (parsed.clarification) {
    // Clarification format: {"clarification": "question"}
    parsedIntent = 'clarification';
    parsedParams = { response: parsed.clarification };
  } else {
    // Unknown format, use first key as intent type
    const firstKey = Object.keys(parsed)[0];
    if (firstKey) {
      parsedIntent = firstKey;
      parsedParams = { response: parsed[firstKey] };
    }
  }

  console.log('Final parsed intent:', parsedIntent);
  console.log('Final parsed params:', parsedParams);

  // Check if the AI is asking for clarification
  if (parsed.needsClarification || parsed.clarification || 
      (parsed.response && (parsed.response.includes('?') || parsed.response.includes('clarify') || parsed.response.includes('specify')))) {
    needsClarification = true;
    clarificationQuestion = parsed.clarificationQuestion || parsed.response || 'Could you provide more details?';
    // Set intent to clarification if not already set
    if (!parsedIntent) {
      parsedIntent = 'clarification';
    }
    conversationState = 'clarifying';
    console.log('AI needs clarification:', clarificationQuestion);
  }

  // Handle clarification responses - when user provides more context in clarifying state
  // Check both AI response and original input context for conversation state
  const inputConversationState = $('Prepare Conversation Context').first()?.json?.conversationState;
  if ((aiResponse.conversationState === 'clarifying' || inputConversationState === 'clarifying') && parsedIntent && parsedIntent !== 'clarification' && parsedIntent !== 'chat') {
    console.log('User provided clarification, AI determined intent:', parsedIntent);
    needsClarification = false;
    conversationState = 'executing';
  }

  // Check if required parameters are missing for certain intents
  if (parsedIntent && !needsClarification) {
    const requiredParams = {
      'move': ['x', 'y', 'z'],
      'goToPlayer': ['player'],
      'collectBlocks': ['block'],
      'placeBlocks': ['material'],
      'craft': ['item'],
      'givePlayer': ['player', 'item'],
      'newAction': ['prompt']
    };

    const required = requiredParams[parsedIntent];
    if (required) {
      const missingParams = required.filter(param => !parsedParams[param] && parsedParams[param] !== 0);
      console.log(`Parameter validation for ${parsedIntent}:`, {
        required,
        parsedParams,
        missingParams
      });
      if (missingParams.length > 0) {
        needsClarification = true;
        clarificationQuestion = `I need more information. Please specify: ${missingParams.join(', ')}`;
        conversationState = 'clarifying';
        console.log('Missing required parameters:', missingParams);
      }
    }
  }
} catch (e) {
  console.log('Failed to parse JSON, treating as chat response:', e.message);
  parsedIntent = 'chat';
  parsedParams = { response: responseText };
}

// Get conversation context for clarification tracking
// Use original data if AI response doesn't have conversation history
const originalData = $('Prepare Conversation Context').first().json || {};
const conversationHistory = aiResponse.conversationHistory || originalData.turns || [];
let clarificationCount = originalData.clarificationCount || 0;
// Fallback: count questions in history if clarificationCount not available
if (!originalData.clarificationCount) {
  clarificationCount = conversationHistory.filter(turn => 
    turn.role === 'assistant' && turn.content && turn.content.includes('?')
  ).length;
}

// Limit clarification attempts
const maxClarifications = 3;
if (clarificationCount >= maxClarifications && needsClarification) {
  console.log('Max clarification attempts reached, proceeding with available info');
  needsClarification = false;
  conversationState = 'executing';
  if (!parsedIntent || parsedIntent === 'chat') {
    parsedIntent = 'chat';
    parsedParams = { response: 'I will do my best with the information provided.' };
  }
}

// originalData already declared above for clarification tracking

return {
  json: {
    // Preserve ALL original context data
    ...originalData,
    // Add parsed AI response data
    intent: parsedIntent,
    params: parsedParams,
    response: parsedParams.response || responseText,
    needsClarification,
    clarificationQuestion,
    conversationState,
    clarificationCount,
    originalResponse: responseText,
    // Preserve AI response for debugging
    aiResponse: aiResponse,
    // Debug info
    parsedSuccessfully: !!parsedIntent
  }
};

const input = $input.first().json;

console.log('=== PREPARE CONVERSATION CONTEXT ===');
console.log('Input structure:', Object.keys(input));
console.log('Full JSON from MongoDB:', JSON.stringify(input, null, 2));

// Get conversation data from the previous Load Conversation History node
const conversation = input.conversation || {};
const turns = input.conversationHistory || [];
const memory = input.memory || '';

console.log('Conversation loaded:', {
  conversationId: conversation.conversationId,
  turnsCount: turns.length,
  hasMemory: !!memory,
  conversationState: input.conversationState || 'initial'
});

// Use current data with fallback to stored data
const botStatus = input.botStatus || {};
const botInventory = input.botInventory || [];
const nearbyPlayers = input.nearbyPlayers || [];

const playerName = input.playerName || input.username || 'Player';
const message = input.message || '';

// Enhanced context building from database
const conversationState = input.conversationState || 'initial';
const needsClarification = input.needsClarification || false;
const clarificationCount = input.clarificationCount || 0;

console.log('Conversation state:', conversationState);
console.log('Total turns:', turns.length);
console.log('Memory length:', memory.length);

// Build comprehensive system prompt matching codebase capabilities
const promptRow = $('Get Prompts').all().find(row => row.json.agent === "Oracle").json.system_prompt;
let systemPrompt = promptRow.replaceAll('{{playerName}}', playerName);

// Add current bot status to system prompt
if (botStatus && Object.keys(botStatus).length > 0) {
  let statusText = 'Status unavailable';
  if (botStatus.position) {
    statusText = `Position: x:${botStatus.position.x?.toFixed(1)}, y:${botStatus.position.y?.toFixed(1)}, z:${botStatus.position.z?.toFixed(1)} | Health: ${botStatus.health}/20 | Action: ${botStatus.current_action || 'Idle'}`;
  }
  systemPrompt += `\n\nCurrent Status: ${statusText}`;
}

// Add inventory info if available
if (botInventory && Array.isArray(botInventory) && botInventory.length > 0) {
  const inventoryText = botInventory.map(item => `${item.name || item.type}(${item.count || item.quantity || 1})`).join(', ');
  systemPrompt += `\nCurrent Inventory: ${inventoryText}`;
} else {
  systemPrompt += `\nCurrent Inventory: Empty (Creative Mode)`;
}

// Add nearby players info
if (nearbyPlayers && nearbyPlayers.length > 0) {
  systemPrompt += `\nNearby Players: ${nearbyPlayers.join(', ')}`;
} else {
  systemPrompt += `\nNearby Players: None detected`;
}

// Add conversation memory if available
if (memory.trim()) {
  systemPrompt += `\n\nConversation Memory: ${memory}`;
}

// Add clarification context if in clarification state
if (conversationState === 'clarifying') {
  systemPrompt += `\n\nIMPORTANT: You are currently in clarification mode (attempt ${clarificationCount + 1}/3). The user's previous request needed more details. Based on their response, either:
1. If you now have enough information, proceed with the appropriate intent
2. If still unclear, ask ONE specific clarifying question
3. If this is attempt 3, proceed with best effort using available information`;
}

// Build messages array following codebase History.getHistory() pattern
const messages = [];

// Add enhanced system message
messages.push({
  role: 'system',
  content: systemPrompt
});

// Add conversation history - smart context management
const maxContextTurns = 15; // Increased from 10 for better context
let contextTurns = turns.slice(-maxContextTurns);

// If we have memory but limited context, add a memory summary message
if (turns.length > maxContextTurns && memory.trim()) {
  messages.push({
    role: 'system',
    content: `Previous conversation summary: ${memory}`
  });
}

// Add recent conversation turns
for (const turn of contextTurns) {
  // Ensure proper role mapping
  let role = 'user';
  if (turn.role === 'assistant' || turn.role === 'bot') {
    role = 'assistant';
  } else if (turn.role === 'system') {
    role = 'system';
  }

  messages.push({
    role: role,
    content: turn.content || turn.message || ''
  });
}

// Add current user message if not already in recent history
const recentMessages = contextTurns.slice(-3);
const alreadyIncluded = recentMessages.some(turn => 
  turn.content === message || turn.content === `${playerName}: ${message}`
);

if (!alreadyIncluded && message) {
  messages.push({
    role: 'user', 
    content: `${playerName}: ${message}`
  });
}

// Log comprehensive context info
console.log('Enhanced conversation context prepared:', {
  totalTurns: turns.length,
  contextTurns: contextTurns.length,
  messagesCount: messages.length,
  hasMemory: !!memory,
  conversationState,
  needsClarification,
  clarificationCount,
  playerName,
  currentMessage: message,
  hasStatus: !!botStatus.position,
  hasInventory: !!botInventory?.length,
  nearbyPlayersCount: (nearbyPlayers || []).length,
  mongoDataReceived: !!conversation._id,
  conversationExists: !!conversation.conversationId
});

return {
  json: {
    // Original data
    ...input,
    // MongoDB conversation data
    conversation: conversation,
    turns: turns,
    memory: memory,
    // Merged current data
    botStatus: botStatus,
    botInventory: botInventory,
    nearbyPlayers: nearbyPlayers,
    // AI context
    messages,
    conversationTurns: turns.length,
    conversationState,
    needsClarification,
    clarificationCount,
    systemPrompt,
    // Player info
    playerName: playerName,
    message: message,
    // Meta
    enhanced: true,
    dataComplete: true
  }
};

const playersHttpResponse = $input.first().json;
const mergedData = $('Merge Status + Inventory').first().json;

console.log('=== FINAL MERGE: PLAYERS DATA ===');
console.log('Merged data keys:', Object.keys(mergedData));
console.log('Players Response:', JSON.stringify(playersHttpResponse, null, 2));
console.log('Current playerName:', mergedData.playerName);
console.log('Current botInventory:', mergedData.botInventory);

// Get nearby players data from the HTTP response
let nearbyPlayers = [];
if (playersHttpResponse && playersHttpResponse.nearby_entities) {
  const entitiesText = playersHttpResponse.nearby_entities;
  console.log('Entities text:', entitiesText);

  // Extract player names from entities text
  const playerMatches = entitiesText.match(/player:\s*([\w]+)/g);
  if (playerMatches) {
    nearbyPlayers = playerMatches.map(match => match.replace('player: ', ''));
  }
}

console.log('Nearby players found:', nearbyPlayers);

// Final result with all data properly merged
const result = {
  ...mergedData,
  nearbyPlayers: nearbyPlayers,
  source: 'inventory_and_players',
  timestamp: new Date().getTime()
};

console.log('Final result keys:', Object.keys(result));
console.log('Final playerName:', result.playerName);
console.log('Final botInventory length:', result.botInventory ? result.botInventory.length : 'undefined');
console.log('Final nearbyPlayers:', result.nearbyPlayers);

return { json: result };

const inventoryHttpResponse = $input.first().json;
const statusData = $('Merge Status Data').first().json;

console.log('=== MERGE STATUS + INVENTORY ===');
console.log('Status data:', statusData);
console.log('Inventory response:', JSON.stringify(inventoryHttpResponse, null, 2));

// Get the actual in-game player name from bot status, not telegram username
let playerName = statusData.playerName; 
// Process inventory data from API response - handle creative mode format
let botInventory = [];
console.log('Processing inventory response...');

if (inventoryHttpResponse) {
  // Handle array response format
  if (Array.isArray(inventoryHttpResponse)) {
    console.log('Inventory is array format');

    for (const item of inventoryHttpResponse) {
      if (item && item.inventory) {
        // Parse inventory text format
        const inventoryText = item.inventory;
        console.log('Parsing inventory text:', inventoryText);

        // Extract items from inventory text
        // Format: "- glass: 1" or "- item_name: quantity"
        const itemMatches = inventoryText.match(/- ([^:]+): (\d+)/g);
        if (itemMatches) {
          for (const match of itemMatches) {
            const parts = match.replace('- ', '').split(': ');
            if (parts.length === 2) {
              botInventory.push({
                name: parts[0].trim(),
                count: parseInt(parts[1]),
                type: parts[0].trim()
              });
            }
          }
        }

        // Check if creative mode
        if (inventoryText.includes('creative mode')) {
          console.log('Bot is in creative mode - unlimited items available');
        }
      }
    }
  } else if (inventoryHttpResponse.inventory) {
    // Direct inventory property
    if (Array.isArray(inventoryHttpResponse.inventory)) {
      botInventory = inventoryHttpResponse.inventory;
    } else if (typeof inventoryHttpResponse.inventory === 'string') {
      // Parse string format
      const inventoryText = inventoryHttpResponse.inventory;
      const itemMatches = inventoryText.match(/- ([^:]+): (\d+)/g);
      if (itemMatches) {
        for (const match of itemMatches) {
          const parts = match.replace('- ', '').split(': ');
          if (parts.length === 2) {
            botInventory.push({
              name: parts[0].trim(),
              count: parseInt(parts[1]),
              type: parts[0].trim()
            });
          }
        }
      }
    }
  }
}

console.log('Processed inventory:', botInventory);
console.log('Inventory count:', botInventory.length);
console.log('Using player name:', playerName);

// Merge all data together
const result = {
  ...statusData,
  playerName: playerName, // Override with in-game name
  botInventory: botInventory,
  inventoryProcessed: true
};

return { json: result };

// === MERGE STATUS DATA ===
