const statusResponse = $input.first().json;

console.log('=== MERGE STATUS ===');
console.log('Input data keys:', Object.keys(inputData));
console.log('Status response full:', JSON.stringify(statusResponse, null, 2));
console.log('Status response type:', typeof statusResponse);

// Process bot status
let botStatus = {};
if (statusResponse && !statusResponse.error) {
  botStatus = statusResponse;
  console.log('Bot Status Retrieved:', botStatus);
} else {
  console.log('Bot Status Error - using defaults');
  botStatus = { error: 'Status unavailable', health: 20, food: 20, position: { x: 0, y: 64, z: 0 } };
}

// Merge input data with bot status
return {
  json: {
    ...inputData,
    botStatus,
    source: 'status'
  }
};

// === NORMALIZE INPUT & LOAD HISTORY ===
const inputData = $('Telegram Bot').first().json;

console.log('=== NORMALIZE INPUT ===');
console.log('Raw input data:', JSON.stringify(inputData, null, 2));

let username, message, chatId, source;

// Handle different input sources
if (inputData.source === 'ingame') {
  // In-game chat forwarding
  username = inputData.username;  // Dynamic player name from in-game
  message = inputData.message;
  chatId = null;  // No chat ID for in-game
  source = 'ingame';
  console.log('Processing IN-GAME chat from player:', username);
} else if (inputData.message) {
  // Telegram input
  username = inputData.message.from?.username || inputData.message.from?.first_name || 'User';
  message = inputData.message.text || '';
  chatId = inputData.message.chat?.id;
  source = 'telegram';
  console.log('Processing TELEGRAM message from user:', username);
} else {
  return { json: { error: 'Unknown input format', rawInput: inputData } };
}

if (!message) {
  return { json: { error: 'No message text', chatId, source } };
}

// Load conversation history and memory from workflow static data
let conversationHistory = [];
let botMemory = '';

try {
  const staticData = $execution.getStaticData('global') || {};
  conversationHistory = staticData.conversationHistory || [];
  botMemory = staticData.botMemory || '';
} catch (e) {
  console.log('Initializing new conversation:', e);
}

// Add user message to history
conversationHistory.push({
  role: 'user',
  content: `${username}: ${message}`,
  timestamp: Date.now(),
  source: source
});

// Keep last 20 messages
if (conversationHistory.length > 20) {
  conversationHistory = conversationHistory.slice(-20);
}

// Save updated history back
try {
  const staticData = $execution.getStaticData('global');
  staticData.conversationHistory = conversationHistory;
  staticData.botMemory = botMemory;
} catch (e) {
  console.log('Could not save conversation history:', e);
}

console.log('Final normalized data:');
console.log('Username (in-game player):', username);
console.log('Message:', message);
console.log('Source:', source);
console.log('Chat ID:', chatId);

return {
  json: {
    username,        // This is now the ACTUAL in-game player name
    message,
    chatId,
    conversationHistory,
    botMemory,
    timestamp: Date.now(),
    source: source,
    playerName:  $input.first().json.playername 
  }
};

// Get the output string from the previous node
const outputString = $input.first().json.output;

console.log('Raw output:', outputString);

try {
  let parsedData;

  // Try to parse directly as JSON first
  try {
    parsedData = JSON.parse(outputString);
    console.log('Parsed as direct JSON');
  } catch (e) {
    // If direct parsing fails, try to extract JSON from code blocks

    // Match various code block formats: ```json ... ```, ```...```, or just raw JSON
    const codeBlockMatch = outputString.match(/```(?:json)?\s*([\s\S]*?)\s*```/);

    if (codeBlockMatch && codeBlockMatch[1]) {
      console.log('Extracted from code block');
      parsedData = JSON.parse(codeBlockMatch[1]);
    } else {
      // Try to find JSON object/array patterns in the string
      const jsonMatch = outputString.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);

      if (jsonMatch) {
        console.log('Extracted JSON pattern');
        parsedData = JSON.parse(jsonMatch[1]);
      } else {
        throw new Error('No JSON found in output');
      }
    }
  }

  console.log('Parsed data:', JSON.stringify(parsedData, null, 2));

  // Return the parsed data as-is (generic, no assumptions about structure)
  return {
    plan: parsedData
  };

} catch (error) {
  console.log('Error parsing JSON:', error.message);
  return [{
    json: {
      error: 'Failed to parse JSON',
      message: error.message,
      rawOutput: outputString
    }
  }];
}

